import type { AidForInternational, DeadlineInfo, DegreeLevel, Field, Region, Selectivity, TuitionBand, University } from "@/lib/types";
import { COMMON_APP, UCAS, deadline, src } from "./sources";

/*
 * Researched expansion (Firecrawl, 1 Nov 2026). See research/NOTES.md for every page read.
 * - `v` marks a fact read from the official page this session → status "verified", lastVerified 2026-11.
 * - Everything else is general guidance ("indicative") or not yet checked ("unverified").
 * - Website/admissions URLs are official university domains.
 */

const VERIFIED = "2026-11";

interface Spec {
  slug: string;
  name: string;
  short?: string;
  country: string;
  cc: string;
  city: string;
  region: Region;
  site: string;
  adm: string;
  type?: "public" | "private";
  founded?: number;
  overview: string;
  fields: Field[];
  programs: string[];
  sel: Selectivity;
  lang?: string;
  levels?: DegreeLevel[];
  tuition: [TuitionBand | null, string];
  aid: [AidForInternational, string, string?, boolean?]; // kind, summary, url, verified
  eng?: { ielts?: number; toefl?: number; note: string; url?: string; v?: boolean };
  test?: [University["testing"]["policy"], string];
  dl?: DeadlineInfo[];
  intl?: string;
  platform?: University["applicationPlatform"];
}

function U(x: Spec): University {
  const org = x.short ? `${x.short} — official site` : `${x.name} — official site`;
  const s = (url: string, verified?: boolean, fallback: "indicative" | "unverified" = "unverified") =>
    verified ? { org, url, status: "verified" as const, lastVerified: VERIFIED } : src(org, url, fallback);
  return {
    slug: x.slug,
    name: x.name,
    shortName: x.short,
    country: x.country,
    countryCode: x.cc,
    city: x.city,
    region: x.region,
    website: x.site,
    admissionsUrl: x.adm,
    applicationPlatform: x.platform,
    type: x.type ?? "public",
    founded: x.founded,
    overview: x.overview,
    levels: x.levels ?? ["undergraduate", "masters", "phd"],
    fields: x.fields,
    notablePrograms: x.programs,
    languageOfInstruction: x.lang ?? "English",
    selectivity: x.sel,
    tuition: { band: x.tuition[0], display: x.tuition[1], source: s(x.adm, false, x.tuition[0] ? "indicative" : "unverified") },
    aid: { kind: x.aid[0], summary: x.aid[1], source: s(x.aid[2] ?? x.adm, x.aid[3], "indicative") },
    english: x.eng
      ? { ielts: x.eng.ielts, toefl: x.eng.toefl, note: x.eng.note, source: s(x.eng.url ?? x.adm, x.eng.v, "indicative") }
      : { note: "Check the official English requirement for your programme.", source: s(x.adm) },
    testing: { policy: x.test?.[0] ?? "varies", note: x.test?.[1] ?? "Confirm testing requirements for your curriculum on the official site.", source: s(x.adm) },
    deadlines: x.dl ?? [deadline("Application", "Varies by programme — confirm on the official admissions site", [], src(org, x.adm, "unverified"))],
    internationalNote: x.intl ?? "International applicants should check programme-specific requirements on the official admissions pages.",
  };
}

const us = (url: string, early = "Early Action / Early Decision") => [
  deadline(early, "Typically 1 November", [11], src("Official admissions", url, "indicative")),
  deadline("Regular Decision", "Typically early January", [1], src("Official admissions", url, "indicative")),
];
const uk = (url: string) => [deadline("UCAS equal-consideration date", "Typically late January", [1], src("UCAS / official admissions", url, "indicative"))];
const au = (url: string) => [deadline("Main intakes", "Two main intakes (around February and July); applications usually open months ahead", [9, 10, 11, 4, 5], src("Official admissions", url, "unverified"))];

